$('#showcase').insertAdjacentHTML('beforebegin',section('problem','The communication problem','0:55',`<div class="section-top"><span class="eyebrow">THE STARTING POINT</span><span class="section-number">01</span></div><div class="research-split"><h2>Information matters.<br><em>So does follow-up.</em></h2><div><p class="lead">Residents need relevant official information and a clear way to reach the office responsible for their concerns.</p><p>When updates and follow-up messages live in separate channels, finding the right information and keeping a consistent record can become difficult.</p><span class="draft-label">PROPOSED PROBLEM STATEMENT · FOR THESIS REVIEW</span></div></div><div class="problem-questions"><div><span>01</span><h3>Where is the update?</h3><p>Find official, relevant community information.</p></div><div><span>02</span><h3>Who should receive this?</h3><p>Reach the appropriate office or stakeholder.</p></div><div><span>03</span><h3>What happens next?</h3><p>Follow communication and concern status.</p></div></div>`,'light-section')+section('objectives','The proposed objectives','0:45',`<div class="section-top"><span class="eyebrow">THE DESIGN RESPONSE</span><span class="section-number">02</span></div><h2>One shared system.<br><em>Two connected experiences.</em></h2><p class="section-intro">Design and develop a centralized Flutter Android application and role-based staff dashboard for community communication in Barili.</p><div class="objective-lines"><div><span>01</span><h3>Centralize official information</h3><p>Announcements, safety notices, and community information.</p></div><div><span>02</span><h3>Make communication two-way</h3><p>Concern submission, receiving offices, replies, and status updates.</p></div><div><span>03</span><h3>Give staff the right access</h3><p>Resident verification, scoped publishing, and operational records.</p></div><div><span>04</span><h3>Evaluate the actual workflows</h3><p>Functionality, usability, intended audiences, and role boundaries.</p></div></div><span class="draft-label">CONDENSED PROPOSED OBJECTIVES · FINAL WORDING SUBJECT TO APPROVED MANUSCRIPT</span>`));
