try{const stage=$('#phone-canvas');scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(32,stage.clientWidth/stage.clientHeight,.1,100);camera.position.z=11;renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(stage.clientWidth,stage.clientHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;stage.appendChild(renderer.domElement);phone=new THREE.Group();const body=new THREE.Mesh(new THREE.BoxGeometry(2.64,5.98,.21,4,4,1),new THREE.MeshStandardMaterial({color:0x29392f,metalness:.85,roughness:.26}));phone.add(body);textureLoader=new THREE.TextureLoader();screenMesh=new THREE.Mesh(new THREE.PlaneGeometry(2.49,5.68),new THREE.MeshBasicMaterial({color:0xffffff}));screenMesh.position.z=.113;phone.add(screenMesh);const button=new THREE.Mesh(new THREE.BoxGeometry(.05,.62,.07),new THREE.MeshStandardMaterial({color:0xa0a899,metalness:1,roughness:.2}));button.position.set(1.345,1.25,0);phone.add(button);scene.add(phone);scene.add(new THREE.AmbientLight(0xffffff,2));const key=new THREE.DirectionalLight(0xe6cb84,5);key.position.set(3,4,5);scene.add(key);const fill=new THREE.DirectionalLight(0x50aa85,3);fill.position.set(-3,1,2);scene.add(fill);new ResizeObserver(()=>{camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix();renderer.setSize(stage.clientWidth,stage.clientHeight)}).observe(stage);stage.addEventListener('pointerdown',e=>{dragX=e.clientX;stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(dragX!==null){rotation+=(e.clientX-dragX)*.007;dragX=e.clientX}});stage.addEventListener('pointerup',()=>dragX=null);stage.addEventListener('pointercancel',()=>dragX=null);function render(t){requestAnimationFrame(render);const progress=Math.max(-1,Math.min(1,($('#showcase').getBoundingClientRect().top-100)/innerHeight));phone.rotation.y=paused||defense?0:rotation+.22+progress*.38;phone.rotation.x=paused||defense?0:-.025;phone.position.y=paused||defense?0:Math.sin(t*.0006)*.06;renderer.render(scene,camera)}requestAnimationFrame(render);textureLoader.load(phoneScreens.home.src,t=>{t.colorSpace=THREE.SRGBColorSpace;screenMesh.material.map=t;screenMesh.material.needsUpdate=true;$('#phone-fallback').classList.add('loaded')});}catch(e){$('#phone-canvas').hidden=true;$('.phone-caption span:last-child').textContent='ACTUAL CAPTURE'}
