const notes={intro:'0:45 · Introduce the team and thesis: E-sugid: Design and Development of a Centralized Community Communication and Information Dissemination System. Establish Barili as the project context. The miniature community is a visual metaphor.',problem:'0:55 · Explain the actual local communication problem using your approved manuscript and requirements evidence. This wording is a proposed design framing, not a measured finding.',objectives:'0:45 · State the general objective and summarize centralization, two-way communication, scoped administration, and evaluation. Confirm the final wording with your approved manuscript.',showcase:'1:10 · Explain the Flutter Android app. Switch the three screens and distinguish resident access from staff administration. The 3D device stays front-facing in defense mode.',announcements:'0:55 · Explain publishers and intended audiences. Open the staff announcement list, resident feed, and calendar. These captures are examples rather than a matched end-to-end announcement.',concerns:'1:40 · Walk the four steps. Explain that a complaint is a separate private workflow. The supplied captures do not yet show a matched resolved case; demonstrate that live or add screenshots later.',emergencies:'1:00 · Select the three alert-editor steps. Explain audience and schedule. Show hotlines. Avoid implying guaranteed emergency response or rescue.',community:'1:05 · Briefly open Bayanihan, Market, and Explore Barili. Keep them supporting the communication story. Market is listings and conversations; the game is an optional extra.',assistant:'0:50 · The displayed two answers are local quick answers with navigation. Distinguish this from cloud-assisted responses; do not describe the captured messages as Gemini-generated.',staff:'1:25 · Switch overview, verification, directory, and report. These are all Barangay Captain captures. Explain assigned scope and distinguish operational counts from research findings.',architecture:'1:00 · Explain Flutter Android and the staff web interface with shared Firebase services. Describe authentication, records, media, backend functions, and notifications, then role boundaries.',evaluation:'0:55 · Present only actual completed testing and evaluation evidence. Add approved procedure, participant details, findings, and limitations here before the real defense.',research:'1:00 · Revisit the contribution: centralized information, resident feedback, and staff coordination. Invite questions. Use the feature galleries to answer follow-up questions.'};
function chapters(){return $$('.chapter')}function goChapter(i){activeChapter=Math.max(0,Math.min(chapters().length-1,i));chapters()[activeChapter].scrollIntoView({behavior:paused||defense?'instant':'smooth'});updateDefense()}function updateDefense(){const list=chapters(),ch=list[activeChapter];$('#chapter-position').textContent=`${String(activeChapter+1).padStart(2,'0')} / ${list.length} · ${ch.dataset.time}`;$('#chapter-title').textContent=ch.dataset.title;$('#chapter-select').value=String(activeChapter);$('#prev-chapter').disabled=activeChapter===0;$('#next-chapter').disabled=activeChapter===list.length-1;$('#presenter-notes').textContent=notes[ch.id]||'Use the actual screens to explain this workflow and its scope.'}
$('#chapter-select').innerHTML=chapters().map((s,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${s.dataset.title}</option>`).join('');$('#chapter-select').onchange=e=>goChapter(Number(e.target.value));
function setDefense(value){defense=value;document.body.classList.toggle('defense-active',value);$('#defense').setAttribute('aria-pressed',value);$('#defense').textContent=value?'Exit defense':'Defense mode';$('#defense-bar').hidden=!value;if(!value)$('#presenter-notes').hidden=true;else{startTime=Date.now();goChapter(0)}}$('#defense').onclick=()=>setDefense(!defense);$$('[data-start-defense]').forEach(x=>x.onclick=()=>setDefense(true));$('#prev-chapter').onclick=()=>goChapter(activeChapter-1);$('#next-chapter').onclick=()=>goChapter(activeChapter+1);$('#notes-toggle').onclick=()=>{const n=$('#presenter-notes');n.hidden=!n.hidden;$('#notes-toggle').setAttribute('aria-expanded',!n.hidden)};
const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');revealObserver.unobserve(e.target)}}),{threshold:.06});$$('.content-section .section-heading,.research-split,.objective-lines,.feature-grid,.architecture,.closing').forEach(x=>{x.classList.add('reveal');revealObserver.observe(x)});
document.addEventListener('keydown',e=>{if(!defense||$('#screen-dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.closest('[role="tablist"]'))return;if(e.key===' '&&/BUTTON|A/.test(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();goChapter(activeChapter+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();goChapter(activeChapter-1)}if(e.key==='Escape')setDefense(false)});setInterval(()=>{if(defense){const s=Math.floor((Date.now()-startTime)/1000);$('#elapsed').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}},1000);
